def _fail(message):
    sys.stderr.buffer.write(
        ('{"error":"%s"}\n' % message).encode("utf-8")
    )


DEFAULT_MAX_EVENTS = 100000
DEFAULT_MAX_LOG_BYTES = 16 * 1024 * 1024
DEFAULT_MAX_CONFIG_BYTES = 1024 * 1024
DEFAULT_MAX_EVENTS_BYTES = 16 * 1024 * 1024
DEFAULT_MAX_DATA_BYTES = 16 * 1024 * 1024
DEFAULT_MAX_ITEMS = 100000
DEFAULT_MAX_OUTPUT_BYTES = 16 * 1024 * 1024
DEFAULT_MAX_STP_WORK = 10000000
DEFAULT_MAX_LOOP_WORK = 10000000
DEFAULT_MAX_FDB_WORK = 10000000
DEFAULT_MAX_FORWARD_WORK = 10000000
DEFAULT_MAX_FORWARD_STP_WORK = 10000000
DEFAULT_MAX_STORM_WORK = 10000000
DEFAULT_MAX_LAG_WORK = 10000000
DEFAULT_MAX_MIRROR_WORK = 10000000
DEFAULT_MAX_ACL_WORK = 10000000
DEFAULT_MAX_QOS_WORK = 10000000
DEFAULT_MAX_SECURITY_WORK = 10000000
DEFAULT_MAX_RELOAD_WORK = 10000000
DEFAULT_MAX_RECORD_WORK = 10000000
DEFAULT_MAX_REPLAY_WORK = 10000000
DEFAULT_MAX_DIFF_WORK = 10000000
DEFAULT_MAX_LINK_WORK = 10000000
DEFAULT_MAX_LINK_FORWARD_WORK = 10000000
# config-export 三项上限的默认值沿用 config-diff（工作量/输入/输出）
DEFAULT_MAX_EXPORT_WORK = DEFAULT_MAX_DIFF_WORK
# config-import 三项上限默认值：工作量沿用 config-export，输入/输出各 1 MiB
DEFAULT_MAX_IMPORT_WORK = DEFAULT_MAX_EXPORT_WORK
CONFIG_IMPORT_MAX_INPUT_BYTES = 1024 * 1024
CONFIG_IMPORT_MAX_OUTPUT_BYTES = 1024 * 1024
_LIMIT_RE = re.compile(r"[1-9][0-9]*")
_READ_CHUNK = 65536


def _limit_value(token):
    """十进制上限串转整数：逐位累加，任意长度按数学整数处理。"""
    value = 0
    for char in token:
        value = value * 10 + ord(char) - ord("0")
    return value


def _parse_limits(tokens, counts, defaults):
    """解析可选上限（个数须属于 counts，均须匹配 [1-9][0-9]*）。

    返回解析值加 defaults 中缺省项；个数不对或任一参数非法返回 None
    （调用方按 usage 处理）。
    """
    if len(tokens) not in counts:
        return None
    if any(_LIMIT_RE.fullmatch(token) is None for token in tokens):
        return None
    parsed = tuple(_limit_value(token) for token in tokens)
    return parsed + defaults[len(parsed):]


def _read_limited(handle, limit):
    """按至多 65536 字节分块读取；超过 limit 即停止并返回 None。

    额度未尽时单次至多请求剩余量，耗尽后只读 1 字节探测超限。
    """
    chunks = []
    total = 0
    while True:
        remaining = limit - total
        if remaining > 0:
            chunk = handle.read(min(_READ_CHUNK, remaining))
        else:
            chunk = handle.read(1)
        if not chunk:
            return b"".join(chunks)
        chunks.append(chunk)
        total += len(chunk)
        if total > limit:
            return None


RECORD_SCHEMA = 1
LOG_KEYS = ("schema", "config", "records", "sha256")
RECORD_KEYS = ("t", "version", "event", "applied", "output")
EVENT_KIND_BY_KEYS = {
    STP_EVENT_KEYS: "link",
    MEMBER_EVENT_KEYS: "member",
    SERVICE_EVENT_KEYS: "service",
    FRAME_KEYS_ACL: "frame",
    RELOAD_EVENT_KEYS: "reload",
    ROLLBACK_EVENT_KEYS: "rollback",
    LINK_FORWARD_LINK_EVENT_KEYS: "link",
    LINK_FORWARD_FRAME_EVENT_KEYS: "frame",
}
_HEX64_RE = re.compile(r"[0-9a-f]{64}\Z")


def _event_kind(event):
    if not isinstance(event, dict):
        raise InvalidInput("bad log event")
    kind = EVENT_KIND_BY_KEYS.get(frozenset(event))
    if kind is None:
        raise InvalidInput("bad log event")
    return kind


def _log_mode(config):
    """record/replay 按 config 形状选模式：loop-detect、link-forward、link-state 或 port-security。"""
    if isinstance(config, dict):
        keys = frozenset(config)
        if keys == LOOP_CONFIG_KEYS:
            return "loop"
        if keys == LINK_FORWARD_CONFIG_KEYS:
            return "link_forward"
        if keys == LINK_STATE_CONFIG_KEYS:
            return "link_state"
    return "security"


def _run_loop_detect(config, events, observe, max_work=None):
    """record/replay 环路模式：校验 loop-detect 配置与事件并执行仿真。

    语义同 loop-detect 子命令；工作量预演（V*(L+1)*(事件数+1)）在
    loop_detect 内、正式仿真前无副作用完成，超限抛 LoopWorkLimit。
    返回 (loop-detect 结果 dict, observer 或 None)。
    """
    bridges, links, vlans = validate_loop_detect_config(config)
    link_ids = {link["id"] for link in links}
    stp_events = validate_stp_events(events, link_ids)
    observer = {} if observe else None
    result = loop_detect(
        links, vlans, stp_events, max_work, observer=observer
    )
    return result, observer


def _run_reload(config, events, observe, max_work=None):
    """reload/record/replay 共用：校验配置与事件并执行 port-security 仿真。

    事件允许 {t, rollback} 回滚事件（语义同 reload-rollback 子命令）。
    返回 (reload 结果 dict, observer 或 None)。全部校验与非法重载检测先于返回。
    max_work 非 None 时（record），全量语义校验后先按 reload 公式无副作用
    预演；首次超过即抛 ReloadWorkLimit，不正式仿真。
    """
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
    ) = validate_security_config(config)
    link_ids = {link["id"] for link in links}
    reload_events, final_config = validate_reload_events(
        events, ports, link_ids, lags, config, allow_rollback=True
    )
    if max_work is not None:
        # 与 reload 入口同一公式：独立链路副本与空状态，不改动既有数据
        reload_work(
            bridges,
            links,
            delay,
            bridge,
            ports,
            age,
            storm,
            lags,
            acl,
            qos,
            security,
            reload_events,
            max_work,
        )
    observer = {} if observe else None
    result = forward_security(
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
        reload_events,
        observer=observer,
    )
    result["config"] = _canonical(final_config)
    return result, observer


def _run_link_forward(config, events, observe, max_work=None):
    """record/replay 链路协商模式：校验 link-forward 配置与事件并执行仿真。

    语义同 link-forward 子命令；max_work 非 None 时全量语义校验后先按
    link-forward 公式无副作用预演，首次超过即抛 LinkForwardWorkLimit，
    不正式仿真。返回 (link-forward 结果 dict, observer 或 None)。
    """
    fwd_ports, caps, age, max_frame, delay = validate_link_forward_config(
        config
    )
    lf_events = validate_link_forward_events(events, fwd_ports)
    if max_work is not None:
        # 与 link-forward 入口同一公式：只计端口数与此前帧数，无副作用
        link_forward_work(fwd_ports, lf_events, max_work)
    observer = {} if observe else None
    result = link_forward(
        fwd_ports, caps, age, max_frame, delay, lf_events, observer=observer
    )
    return result, observer


def _run_link_state(config, events, observe, max_work=None):
    """record/replay 链路状态模式：校验 link-state 配置与事件并执行仿真。

    语义同 link-state 子命令；max_work 非 None 时全量语义校验后先按
    link-state 公式无副作用预演，首次超过即抛 LinkWorkLimit，不正式
    协商。返回 (link-state 结果 dict, observer 或 None)。
    """
    ports, delay = validate_link_state_config(config)
    ls_events = validate_link_state_events(events, ports)
    if max_work is not None:
        # 与 link-state 入口同一公式：每事件处理到期项前以 pending 数 Q
        # 累计 Q+1，无副作用
        link_state_work(ls_events, ports, delay, max_work)
    observer = {} if observe else None
    result = link_state(ls_events, ports, delay, observer=observer)
    return result, observer


def _build_log_doc(config, events, items):
    """构造 LOG 文档（含 sha256）；records 与事件等长、同序。"""
    if len(events) != len(items):
        raise InvalidInput("bad log")
    mode = _log_mode(config)
    records = []
    # version 初值 0，取事件后值；安全模式每次 reload/rollback（无变化
    # 亦算）加 1，环路模式链路 up 实际改变（applied）才加 1，链路协商
    # 模式仅 applied 链路项加 1（帧项恒 applied 但不计），链路状态模式
    # 仅 applied 项加 1
    version = 0
    for event, observed in zip(events, items):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log")
        if mode == "loop":
            if observed["applied"]:
                version += 1
        elif mode == "link_forward":
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        records.append(
            {
                "t": event["t"],
                "version": version,
                "event": _canonical(event),
                "applied": observed["applied"],
                "output": observed["output"],
            }
        )
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


def _log_prefix_bytes(doc):
    """sha256 摘要文本：schema,config,records 规范序列化后含 LF。"""
    prefix = {
        "schema": doc["schema"],
        "config": doc["config"],
        "records": doc["records"],
    }
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _log_bytes(doc):
    ordered = {key: doc[key] for key in LOG_KEYS}
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _assert_canonical_order(value):
    """config/event 内对象键须递归按 Unicode 码点升序，数组保序。"""
    if isinstance(value, dict):
        keys = list(value)
        if keys != sorted(keys):
            raise InvalidInput("bad log key order")
        for item in value.values():
            _assert_canonical_order(item)
    elif isinstance(value, list):
        for item in value:
            _assert_canonical_order(item)


def _json_equal(a, b):
    """JSON 值深比较；bool 不与 int 混同，键序无关，数组保序。"""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(
            _json_equal(a[key], b[key]) for key in a
        )
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(
            _json_equal(x, y) for x, y in zip(a, b)
        )
    if a is None or b is None:
        return a is None and b is None
    return type(a) is type(b) and a == b


def _validate_log_shape(log):
    """严格校验 LOG 字段、类型、键序；不含语义重放。"""
    if not isinstance(log, dict) or list(log) != list(LOG_KEYS):
        raise InvalidInput("bad log")
    if not _is_int(log["schema"]) or log["schema"] != RECORD_SCHEMA:
        raise InvalidInput("bad log schema")
    config = log["config"]
    if not isinstance(config, dict):
        raise InvalidInput("bad log config")
    _assert_canonical_order(config)
    records = log["records"]
    if not isinstance(records, list):
        raise InvalidInput("bad log records")
    for record in records:
        if not isinstance(record, dict) or list(record) != list(RECORD_KEYS):
            raise InvalidInput("bad log record")
        if not _is_int(record["t"]) or record["t"] < 0:
            raise InvalidInput("bad log t")
        if not _is_int(record["version"]) or record["version"] < 0:
            raise InvalidInput("bad log version")
        event = record["event"]
        if not isinstance(event, dict):
            raise InvalidInput("bad log event")
        _assert_canonical_order(event)
        _event_kind(event)
        if not isinstance(record["applied"], bool):
            raise InvalidInput("bad log applied")
        if record["output"] is not None and not isinstance(
            record["output"], dict
        ):
            raise InvalidInput("bad log output")
    digest = log["sha256"]
    if not isinstance(digest, str) or _HEX64_RE.fullmatch(digest) is None:
        raise InvalidInput("bad log sha256")


def _verify_records(log, events, items):
    """重放后逐项核对 t/version/event/applied/output。"""
    records = log["records"]
    if len(records) != len(items):
        raise InvalidInput("bad log records")
    mode = _log_mode(log["config"])
    version = 0
    for event, observed, record in zip(events, items, records):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log record")
        if mode == "loop":
            if observed["applied"]:
                version += 1
        elif mode == "link_forward":
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        if record["t"] != event["t"]:
            raise InvalidInput("bad log t")
        if record["version"] != version:
            raise InvalidInput("bad log version")
        if not _json_equal(record["event"], _canonical(event)):
            raise InvalidInput("bad log event")
        if record["applied"] is not observed["applied"]:
            raise InvalidInput("bad log applied")
        if not _json_equal(record["output"], observed["output"]):
            raise InvalidInput("bad log output")


def _atomic_write(path, payload):
    """同目录临时文件 + os.replace 原子写入；失败不改动目标。"""
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(prefix=".switch-log-", dir=directory)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def _result_bytes(result):
    """stdout 载荷：紧凑 UTF-8 JSON 加一个 LF。"""
    return (
        json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
        + b"\n"
    )


def _cmd_record(
    config_path,
    events_path,
    log_path,
    max_events,
    max_log_bytes,
    max_config_bytes,
    max_events_bytes,
    max_output_bytes,
    max_record_work,
):
    try:
        with open(config_path, "rb") as config_handle, open(
            events_path, "rb"
        ) as events_handle:
            # 两文件均可读后，先判 CONFIG 原始字节，再判 EVENTS 原始字节
            config_raw = _read_limited(config_handle, max_config_bytes)
            if config_raw is None:
                _fail("config_limit")
                return 5
            events_raw = _read_limited(events_handle, max_events_bytes)
            if events_raw is None:
                _fail("events_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        # 事件上界先于解析与预演判定；超限时绝不触碰 LOG
        events_preview = parse_json(events_raw)
        if isinstance(events_preview, list) and len(events_preview) > max_events:
            _fail("event_limit")
            return 5
        # 先无副作用预演：解析、全部校验与各重载点检测均在内存完成；
        # 工作量预演在语义校验后、正式仿真与 LOG 构造前，超限绝不触碰 LOG
        config = parse_json(config_raw)
        events = events_preview
        mode = _log_mode(config)
        if mode == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_record_work
            )
        elif mode == "link_forward":
            result, observer = _run_link_forward(
                config, events, True, max_record_work
            )
        elif mode == "link_state":
            result, observer = _run_link_state(
                config, events, True, max_record_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_record_work
            )
        doc = _build_log_doc(config, events, observer["items"])
        payload = _log_bytes(doc)
        # 字节上界（含末尾 LF）在写入前判定；等于上限合法
        if len(payload) > max_log_bytes:
            _fail("log_limit")
            return 5
        # 输出上界在 log_limit 之后、原子写 LOG 之前判定；超限时绝不触碰 LOG
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
        _atomic_write(log_path, payload)  # 成功后才原子写 LOG
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        LoopWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
    ):
        _fail("record_work_limit")
        return 5
    except OSError:
        _fail("file_not_found")
        return 3
    sys.stdout.buffer.write(output)
    return 0


def _cmd_replay(
    log_path, max_events, max_log_bytes, max_output_bytes, max_replay_work
):
    try:
        with open(log_path, "rb") as handle:
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    # 字节上界先判定（分块读取、超限即停，含末尾 LF）
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        log = parse_json(log_raw)  # 全量校验先于重放
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        config = log["config"]
        events = [record["event"] for record in log["records"]]
        # records 上界在解析校验后、重放前判定
        if len(log["records"]) > max_events:
            _fail("event_limit")
            return 5
        # 状态语义校验后先按 record 同一公式无副作用预演；首次超限即停止，
        # 不正式重放，LOG 保持不动
        mode = _log_mode(config)
        if mode == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_replay_work
            )
        elif mode == "link_forward":
            result, observer = _run_link_forward(
                config, events, True, max_replay_work
            )
        elif mode == "link_state":
            result, observer = _run_link_state(
                config, events, True, max_replay_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_replay_work
            )
        _verify_records(log, events, observer["items"])
        # 重放重建的 LOG 须与原文件逐字节一致（含 sha256 与 LF）
        rebuilt = _build_log_doc(config, events, observer["items"])
        if _log_bytes(rebuilt) != log_raw:
            raise InvalidInput("bad log")
        # 输出上界在全部日志语义与重放核对成功后判定；LOG 保持不动
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        LoopWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
    ):
        _fail("replay_work_limit")
        return 5
    sys.stdout.buffer.write(output)
    return 0


CONFIG_DIFF_MAX_INPUT_BYTES = 1024 * 1024


def _json_pointer_token(token):
    """RFC6901 reference token 转义：~ 编码为 ~0，/ 编码为 ~1。"""
    return token.replace("~", "~0").replace("/", "~1")


def _diff_collect(old, new, path, changes):
    """按键序无关契约收集 OLD、NEW 的差异项到 changes。

    对象递归，键按 Unicode 码点升序深度优先；数组整体比较且顺序敏感，
    整组不同仅出一项；标量按 JSON 类型与值比较。path 为 RFC6901 JSON
    Pointer（根为 ""）。仅不同的数组或标量（及缺失对象键）生成项。
    """

def _validate_link_state_rates(rates):
    # rates 为 10/100/1000/10000 的非空严格递增子集
    if not isinstance(rates, list) or not rates:
        raise InvalidInput("bad rates")
    if any(
        not _is_int(rate) or rate not in LINK_STATE_RATES for rate in rates
    ):
        raise InvalidInput("bad rates")
    if any(rates[i] >= rates[i + 1] for i in range(len(rates) - 1)):
        raise InvalidInput("rates not increasing")
    return tuple(rates)


def _validate_link_state_modes(modes):
    # modes 为 half/full 的非空子序列（保序、互异、非空）
    if not isinstance(modes, list) or not modes:
        raise InvalidInput("bad modes")
    if any(
        not isinstance(mode, str) or mode not in LINK_STATE_MODES
        for mode in modes
    ):
        raise InvalidInput("bad modes")
    if len(set(modes)) != len(modes):
        raise InvalidInput("bad modes")
    if list(modes) != sorted(modes, key=LINK_STATE_MODES.index):
        raise InvalidInput("modes not a subsequence")
    return tuple(modes)


def validate_link_state_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != LINK_STATE_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    delay = config["delay"]
    if not _is_int(delay) or delay <= 0:
        raise InvalidInput("bad delay")
    ports = config["ports"]
    if not isinstance(ports, list) or not ports:
        raise InvalidInput("ports must be a non-empty list")
    names = []
    result = []
    for port in ports:
        if (
            not isinstance(port, dict)
            or frozenset(port) != LINK_STATE_PORT_KEYS
        ):
            raise InvalidInput("bad port")
        name = port["name"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        names.append(name)
        result.append(
            (
                name,
                _validate_link_state_rates(port["rates"]),
                _validate_link_state_modes(port["modes"]),
            )
        )
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    return result, delay


def validate_link_state_events(events, ports):
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    port_set = {name for name, _, _ in ports}
    result = []
    prev_t = None
    for event in events:
        if (
            not isinstance(event, dict)
            or frozenset(event) != LINK_STATE_EVENT_KEYS
        ):
            raise InvalidInput("bad event")
        t = event["t"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        port = event["port"]
        if not isinstance(port, str) or port not in port_set:
            raise InvalidInput("unknown port")
        admin = event["admin"]
        peer = event["peer"]
        if not isinstance(admin, bool) or not isinstance(peer, bool):
            raise InvalidInput("bad admin/peer")
        rates = _validate_link_state_rates(event["rates"])
        modes = _validate_link_state_modes(event["modes"])
        result.append((t, port, admin, peer, rates, modes))
    return result


def link_state(events, ports, delay, observer=None):
    if observer is not None:  # record：逐事件记录 applied 与对应 results 项
        observer["items"] = []
    caps = {name: (rates, modes) for name, rates, modes in ports}
    # 生效状态：("down",)/("bad",)/("up", rate, mode)；两状态初始皆 false
    committed = {name: ("down",) for name, _, _ in ports}
    pending = {}  # name -> (rate, mode, deadline)；仅 up 目标需协商
    results = []
    for t, port, admin, peer, rates, modes in events:
        # 先完成截止 <= t 的协商
        for name in [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        # 再替换该口并计算目标
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            applied = False  # 未变不重置
        elif target[0] == "up":
            # 目标变化即进入 wait 并于 t+delay 完成
            pending[port] = (target[1], target[2], t + delay)
            applied = True
        else:
            # down/bad 立即生效
            pending.pop(port, None)
            committed[port] = target
            applied = True
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
            else:
                state, rate, mode = now[0], None, None
        results.append(
            {"t": t, "port": port, "state": state, "rate": rate, "mode": mode}
        )
        if observer is not None:
            observer["items"].append(
                {"kind": "link", "t": t, "applied": applied,
                 "output": results[-1]}
            )
    return {"results": results}


def link_state_work(events, ports, delay, limit):
    """link-state 的工作量预演：独立 committed/pending 状态，无副作用。

    W 初值 0；逐事件在完成截止 <= t 的协商前，令 Q 为 pending 数，累计
    Q+1；再沿用 link_state 规则完成到期项、替换该口状态并计算
    down/bad/up 目标，目标未变不重置，变为 up 则进入 wait。等于上限
    合法，首次超过即抛 LinkWorkLimit，不访问后续事件。
    """
    caps = {name: (rates, modes) for name, rates, modes in ports}
    committed = {name: ("down",) for name, _, _ in ports}
    pending = {}  # name -> (rate, mode, deadline)
    work = 0
    for t, port, admin, peer, rates, modes in events:
        work += len(pending) + 1
        if work > limit:
            raise LinkWorkLimit()
        for name in [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            pass  # 未变不重置
        elif target[0] == "up":
            pending[port] = (target[1], target[2], t + delay)
        else:
            pending.pop(port, None)
            committed[port] = target


